
(()=>{
 const $=id=>document.getElementById(id);let demoOn=true,board='points',streak='study',month='';
 const people=[
  {name:'Dylan Coles',avatar:'data:image/jpeg;base64,',points:186,previous:142,study:42,action:18,own:true},
  {name:'Tyler Long',avatar:'data:image/jpeg;base64,',points:172,previous:151,study:37,action:16},
  {name:'Booker Mays',avatar:'data:image/jpeg;base64,',points:159,previous:108,study:34,action:14},
  {name:'Jon Coburn',avatar:'data:image/jpeg;base64,',points:137,previous:119,study:29,action:12},
  {name:'Jaalyn Steen',avatar:'data:image/jpeg;base64,',points:121,previous:96,study:25,action:10},
  {name:'Jarrius Holley',avatar:'data:image/jpeg;base64,',points:108,previous:101,study:21,action:9},
  {name:'Haili Steen',avatar:'data:image/jpeg;base64,',points:94,previous:88,study:18,action:7},
  {name:'Andrew Jones',avatar:'data:image/jpeg;base64,',points:89,previous:80,study:16,action:6},
  {name:'Derrick Bean',avatar:'data:image/jpeg;base64,',points:82,previous:76,study:14,action:5}
 ];
 const gains=[['Daily audio & reading',30],['Prospect outreach',10],['Customer calls',6],['Follow-ups',4],['PQIs completed',8],['New customers',6],['Strong Start reviews',8],['Finished a book',8]];
 const monthKey=d=>d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');
 const monthLabel=k=>{const [y,m]=k.split('-').map(Number);return new Date(y,m-1,1).toLocaleDateString(undefined,{month:'long',year:'numeric'})};
 function available(){let d=new Date(),out=[];for(let i=0;i<7;i++){let x=new Date(d.getFullYear(),d.getMonth()-i,1);out.push(monthKey(x))}return out}
 function dataFor(k){let keys=available(),idx=Math.max(0,keys.indexOf(k));return people.map((p,i)=>({...p,points:Math.max(0,p.points-idx*(9+i*2)+(idx%2?i*3:0)),previous:Math.max(0,p.previous-idx*(7+i)),study:Math.max(0,p.study-idx*(2+i%3)),action:Math.max(0,p.action-idx*(1+i%2))}))}
 function esc(t){return String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
 function podium(list,metric,label){let order=[list[1],list[0],list[2]];return '<div class="wc-podium">'+order.map((p,i)=>{let rank=i===0?2:i===1?1:3,place=rank===1?'first':rank===2?'second':'third';return '<div class="wc-podium-card '+place+'"><div class="wc-podium-rank"><span class="wc-place-badge">'+rank+'</span></div><div class="wc-podium-avatar '+(p.own?'wc-own-avatar':'')+'"><img class="'+(p.own?'wc-own-avatar-img':'')+'" alt="'+esc(p.name)+' avatar" src="'+esc(p.avatar)+'"></div><div class="wc-podium-name">'+esc(p.name)+'</div><div class="wc-podium-score">'+metric(p)+'</div><div class="wc-podium-unit">'+label+'</div></div>'}).join('')+'</div>'}
 function rows(list,metric,unit){return '<div class="wc-demo-rows">'+list.slice(3,5).map((p,i)=>'<div class="wc-demo-row"><div class="rank">'+(i+4)+'</div><img class="mini-avatar" src="'+esc(p.avatar||'')+'" alt="'+esc(p.name)+' avatar" loading="eager"><div class="wc-demo-person"><div class="person">'+esc(p.name)+'</div><div class="detail">Coburn team member</div></div><div class="score">'+metric(p)+' <span style="font-size:9px;color:#9aabc1">'+unit+'</span></div></div>').join('')+'</div>'}
 function setMonth(){let sel=$('wc-board-period');if(!sel)return;let months=available();sel.innerHTML=months.map(k=>'<option value="'+k+'">'+monthLabel(k)+'</option>').join('');if(!months.includes(month))month=months[0];sel.value=month}
 function render(){let panel=$('wc-board-empty');if(!panel)return;let period=month||monthKey(new Date()),list=dataFor(period),metric,label,subtitle;
  if(board==='points'){metric=p=>p.points;label='POINTS';subtitle='Most business-building points in '+monthLabel(period)}
  else if(board==='improved'){metric=p=>p.points-p.previous;list=list.map(p=>({...p,improvement:Math.max(0,p.points-p.previous)})).sort((a,b)=>b.improvement-a.improvement);metric=p=>'+'+p.improvement;label='POINTS';subtitle='Point increase in '+monthLabel(period)+' vs. previous month'}
  else{metric=p=>p[streak];label=streak==='study'?'DAYS':'WEEKS';list=list.sort((a,b)=>b[streak]-a[streak]);subtitle=streak==='study'?'Daily audio + reading completed consecutively':'Consecutive qualifying Monday–Sunday action weeks'}
  $('wc-board-title').textContent=board==='points'?'TOTAL POINTS':board==='streak'?'LONGEST STREAK':'MOST IMPROVED';$('wc-board-subtitle').textContent=subtitle;$('wc-board-period').style.display=board==='streak'?'none':'';$('wc-streak-switch').hidden=board!=='streak';$('wc-board-scope').textContent='Top 5 • SAMPLE DATA • '+(board==='streak'?'Consecutive '+(streak==='study'?'days':'weeks'):monthLabel(period));
  panel.className='wc-demo-board';panel.innerHTML=podium(list,metric,label)+rows(list,metric,label)+'<div class="wc-demo-muted">Demo profiles and scores are fictional. No activity has been written to Supabase.</div>';
  const stats=$('wc-personal-demo-stats');if(stats)stats.innerHTML='<div class="wc-personal-stat streak"><strong>🔥 8</strong><span>STUDY DAY STREAK</span></div><div class="wc-personal-stat streak"><strong>🔥 6</strong><span>ACTION WEEK STREAK</span></div><div class="wc-personal-stat"><strong>42</strong><span>MONTHLY POINTS</span></div><div class="wc-personal-stat"><strong>+16</strong><span>GAINED LAST MONTH</span></div>';
  const gains=$('wc-gains-demo-list');if(gains)gains.innerHTML=gainsData().map(([n,v])=>'<div class="wc-gain-item"><span>'+esc(n)+'</span><span>+'+v+' pts</span></div>').join('')+'<div class="wc-gain-item" style="border-color:#9b7b39"><strong>Total sample gains</strong><strong>+42 pts</strong></div>';
 }
 function gainsData(){return [['Daily audio & reading',10],['Prospect outreach',5],['Customer calls',4],['PQI completed',8],['New customers',6],['Strong Start review',4],['Finished a book',5]]}
 window.switchWcBoard=function(v){if(!['points','streak','improved'].includes(v))return;board=v;document.querySelectorAll('.wc-tab').forEach(b=>b.setAttribute('aria-selected',String(b.id==='wc-tab-'+v)));if(v==='streak')window.switchWcStreak(streak);else render()};
 window.switchWcStreak=function(v){if(!['study','action'].includes(v))return;streak=v;$('wc-study-button').setAttribute('aria-pressed',String(v==='study'));$('wc-action-button').setAttribute('aria-pressed',String(v==='action'));if(board==='streak')render()};
 window.refreshWcBoardPeriod=function(){month=$('wc-board-period').value||month;render()};
 window.toggleWcDemo=function(){demoOn=!demoOn;$('wc-demo-bar').style.display='flex';$('wc-demo-bar').querySelector('strong').textContent=demoOn?'✦ SAMPLE DATA PREVIEW':'PREVIEW PAUSED';$('wc-demo-bar').querySelector('div div').textContent=demoOn?'Illustrative rankings only — not real team results or saved activity':'Sample rankings are hidden. No live scoring data is connected.';$('wc-demo-toggle').textContent=demoOn?'Turn Preview Off':'Turn Preview On';if(!demoOn){$('wc-board-empty').className='wc-empty';$('wc-board-empty').textContent='Sample preview is off. The live Winners Circle scoring connection has not been installed yet; no real rankings or scores are shown.';$('wc-board-scope').textContent='Top 5 • Coburn hierarchy';$('wc-personal-demo-stats').innerHTML='';$('wc-gains-demo-list').innerHTML='';$('wc-demo-toggle').textContent='Turn Preview On';}else{render()}};
 // Add clearly labelled sample metrics without changing the existing profile/avatar system.
 const dash=$('wc-personal-dashboard');if(dash&&!$('wc-personal-demo-stats')){let d=document.createElement('div');d.id='wc-personal-demo-stats';d.className='wc-personal-stats';const head=dash.querySelector('.wc-personal-head');if(head)head.insertAdjacentElement('afterend',d);else dash.appendChild(d)}
 const gainsSection=$('wc-personal-gains');if(gainsSection&&!$('wc-gains-demo-list')){let n=gainsSection.querySelector('.note');if(n)n.textContent='Illustrative sample activity only — not connected to your saved records.';let d=document.createElement('div');d.id='wc-gains-demo-list';d.className='wc-gain-list';gainsSection.appendChild(d)}
 const demoBar=$('wc-demo-bar'), winners=$('winners');if(demoBar&&winners)winners.appendChild(demoBar);
 setMonth();render();const currentAvatar=$('wc-avatar-image');if(currentAvatar&&!currentAvatar.hidden&&currentAvatar.src)document.querySelectorAll('.wc-own-avatar-img').forEach(img=>img.src=currentAvatar.src);
})();
